"use client";

import {
  TextField as AriaTextField,
  type TextFieldProps as AriaTextFieldProps,
  composeRenderProps,
  FieldError,
  Input,
  Label,
  Text,
} from "react-aria-components";
import { cn } from "./utils";
import {
  fieldDescriptionStyles,
  fieldErrorStyles,
  fieldInputStyles,
  fieldLabelStyles,
} from "./field-styles";

export interface TextFieldProps
  extends Omit<AriaTextFieldProps, "className" | "children"> {
  label?: string;
  description?: string;
  placeholder?: string;
  ref?: React.Ref<HTMLDivElement>;
  className?: AriaTextFieldProps["className"];
  children?: AriaTextFieldProps["children"];
}

export function TextField({
  label,
  description,
  placeholder,
  className,
  children,
  ...props
}: TextFieldProps) {
  return (
    <AriaTextField
      {...props}
      data-slot="text-field"
      className={composeRenderProps(className, (className) =>
        cn("flex w-full flex-col gap-2", className),
      )}
    >
      {children ?? (
        <>
          {label && <TextFieldLabel>{label}</TextFieldLabel>}
          <TextFieldInput placeholder={placeholder} />
          {description && (
            <TextFieldDescription>{description}</TextFieldDescription>
          )}
          <TextFieldError />
        </>
      )}
    </AriaTextField>
  );
}

export function TextFieldLabel({
  className,
  ...props
}: React.ComponentProps<typeof Label>) {
  return (
    <Label
      {...props}
      data-slot="text-field-label"
      className={cn(fieldLabelStyles, className)}
    />
  );
}

export function TextFieldInput({
  className,
  ...props
}: React.ComponentProps<typeof Input>) {
  return (
    <Input
      {...props}
      data-slot="text-field-input"
      className={composeRenderProps(className, (className) =>
        cn(fieldInputStyles, "px-3.5", className),
      )}
    />
  );
}

export function TextFieldDescription({
  className,
  ...props
}: React.ComponentProps<typeof Text>) {
  return (
    <Text
      {...props}
      slot="description"
      data-slot="text-field-description"
      className={cn(fieldDescriptionStyles, className)}
    />
  );
}

export function TextFieldError({
  className,
  ...props
}: React.ComponentProps<typeof FieldError>) {
  return (
    <FieldError
      {...props}
      data-slot="text-field-error"
      className={cn(fieldErrorStyles, className)}
    />
  );
}

"use client";

import { EnvelopeSimpleIcon, KeyIcon } from "@phosphor-icons/react";
import { useState } from "react";
import { Button } from "../../../components/vip-ui/button";
import { Form } from "../../../components/vip-ui/form";
import { Link } from "../../../components/vip-ui/link";
import { Separator } from "../../../components/vip-ui/separator";
import { TextField } from "../../../components/vip-ui/text-field";

export function EmailLinkForm() {
  const [sentTo, setSentTo] = useState<string | null>(null);
  const [resends, setResends] = useState(0);

  if (sentTo) {
    return (
      <div className="grid gap-6 text-center">
        <span className="mx-auto grid size-12 place-items-center rounded-full bg-accent text-accent-foreground">
          <EnvelopeSimpleIcon size={22} aria-hidden="true" />
        </span>
        <div className="grid gap-2">
          <h1 className="text-2xl font-semibold tracking-[-0.04em]">
            Check your email
          </h1>
          <output className="block text-sm leading-6 text-muted-foreground">
            We sent a sign-in link to{" "}
            <span className="font-medium text-foreground">{sentTo}</span>. The
            link expires in 10 minutes.
          </output>
        </div>
        <div className="grid gap-2">
          <Button variant="outline" onPress={() => setResends(resends + 1)}>
            Send the link again
          </Button>
          <Button variant="ghost" onPress={() => setSentTo(null)}>
            Use a different email
          </Button>
        </div>
        <output className="block min-h-4 text-xs text-muted-foreground">
          {resends > 0 && "We sent a new link. Only the latest link works."}
        </output>
      </div>
    );
  }

  return (
    <Form
      onSubmit={(event) => {
        event.preventDefault();
        const data = new FormData(event.currentTarget);
        setResends(0);
        setSentTo(String(data.get("email")));
      }}
    >
      <div className="grid gap-2 text-center">
        <h1 className="text-2xl font-semibold tracking-[-0.04em]">
          Sign in to Northwind
        </h1>
        <p className="text-sm leading-6 text-muted-foreground">
          Enter your email. We send you a link to sign in.
        </p>
      </div>
      <TextField
        label="Email"
        name="email"
        type="email"
        autoComplete="email"
        placeholder="you@company.com"
        isRequired
      />
      <Button type="submit" className="w-full">
        Email me a link
      </Button>
      <div className="flex items-center gap-3 text-xs text-muted-foreground">
        <Separator className="flex-1" />
        or
        <Separator className="flex-1" />
      </div>
      <Button variant="outline" className="w-full">
        <KeyIcon size={16} aria-hidden="true" />
        Sign in with a passkey
      </Button>
      <p className="text-center text-xs leading-5 text-muted-foreground">
        When you continue, you agree to the <Link href="#">terms</Link> and the{" "}
        <Link href="#">privacy policy</Link>.
      </p>
    </Form>
  );
}

